COMMENT ON COLUMN commission_payout_line.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN commission_payout_line.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_commission_payout_line_tenant ON commission_payout_line (tenant_id, created_at);
CREATE INDEX ix_commission_payout_line_commission_payout_run_id ON commission_payout_line (commission_payout_run_id);
CREATE INDEX ix_commission_payout_line_beneficiary_wallet_id ON commission_payout_line (beneficiary_wallet_id);
CREATE INDEX ix_commission_payout_line_beneficiary_agent_id ON commission_payout_line (beneficiary_agent_id);
CREATE INDEX ix_commission_payout_line_wallet_transaction_id ON commission_payout_line (wallet_transaction_id);
ALTER TABLE commission_payout_line ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON commission_payout_line USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_commission_payout_line_append_only BEFORE UPDATE OR DELETE ON commission_payout_line FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA commission TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA commission TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA commission GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
